SELECT c.relname||chr(9)||string_agg(quote_ident(a.attname), ',' ORDER BY a.attname COLLATE "C") FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE c.relnamespace='public'::regnamespace AND c.relkind='r' AND c.relname IN ('vendas','itens_venda','vendas_pagamentos','caixas','movimentacoes_caixa','estoque','produtos','usuarios','clientes','lojas','formas_pagamento','contas_financeiras','contas_pagar','contas_receber','pdv_config','documentos_fiscais_pendentes') GROUP BY c.relname ORDER BY array_position(ARRAY['vendas','itens_venda','vendas_pagamentos','caixas','movimentacoes_caixa','estoque','produtos','usuarios','clientes','lojas','formas_pagamento','contas_financeiras','contas_pagar','contas_receber','pdv_config','documentos_fiscais_pendentes']::text[], c.relname::text)
